    skLineSegment(p0, "line1", { "start" : vector(-8, 10) * millimeter, "end" : vector(8, 10) * millimeter });
    skArc(p0, "arc1", { "start" : vector(8, 10) * millimeter, "mid" : vector(9.414214, 9.414214) * millimeter, "end" : vector(10, 8) * millimeter });
    skLineSegment(p0, "line2", { "start" : vector(10, 8) * millimeter, "end" : vector(10, -8) * millimeter });
    skArc(p0, "arc2", { "start" : vector(10, -8) * millimeter, "mid" : vector(9.414214, -9.414214) * millimeter, "end" : vector(8, -10) * millimeter });
    skLineSegment(p0, "line3", { "start" : vector(8, -10) * millimeter, "end" : vector(-8, -10) * millimeter });
    skArc(p0, "arc3", { "start" : vector(-8, -10) * millimeter, "mid" : vector(-9.414214, -9.414214) * millimeter, "end" : vector(-10, -8) * millimeter });
    skLineSegment(p0, "line4", { "start" : vector(-10, -8) * millimeter, "end" : vector(-10, 8) * millimeter });
    skArc(p0, "arc4", { "start" : vector(-10, 8) * millimeter, "mid" : vector(-9.414214, 9.414214) * millimeter, "end" : vector(-8, 10) * millimeter });
    skSolve(p0);
