    skCircle(p1, "circle1", { "center" : vector(0, 0) * millimeter, "radius" : 10 * millimeter });
    skSolve(p1);
    loft(context, id + "loft1", { "sheetProfilesArray" : [{ "sheetProfileEntities" : qSketchRegion(id + "p0") }, { "sheetProfileEntities" : qSketchRegion(id + "p1") }], "bodyType" : ExtendedToolBodyType.SOLID, "operationType" : NewBodyOperationType.NEW, "startCondition" : LoftEndDerivativeType.DEFAULT, "endCondition" : LoftEndDerivativeType.DEFAULT });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "loft1", EntityType.BODY), BodyType.SOLID)), "volume" : roundToPrecision(evVolume(context, { "entities" : qBodyType(qCreatedBy(id + "loft1", EntityType.BODY), BodyType.SOLID) }) / millimeter ^ 3, 6) };
}

